GenerateOffersResults = {
    init: async function(app, container, instance) {
        // extract the packaged data
        var dataPath = "DMS/Data/Transactions/Processed/" + instance.Start.split("T")[0] + "/";
        var app = await api.get("ContentManagement/App(" + app.Id + ")");
        app.Config = JSON.parse(app.ConfigJson);
        await api.get(dataPath +  "FundingReport-" + instance.Id + ".json").then((report) => {
            GenerateOffersResults.setupTSet(report, $(".container[name=offers]", container));
        }).catch((err) => error(err));
    },
    setupTSet: function(report, container) {
        container.append($("template[name=transactionStats]").html());
        $("[name=added]", container).append(report.Results.filter(r => r.Success).length);
        $("[name=updated]", container).append(0);
        $("[name=failures] > a", container).append(report.Results.filter(r => !r.Success).length);
        $("[name=failures] > a", container).on("click", function(e) { GenerateOffersResults.openFailureDialog(report.Results.filter(r => !r.Success)); });
        $("[name=total]", container).append(report.Results.length);
    },

    openFailureDialog: function(failures) {
        // transform the source data to extract the key details
        var itemData = failures.map(function(i) { 
            return  {
                clientRef: GenerateOffersResults.getClientRef(i.Item),
                transactions: i.Item.Transactions.join(),
                message: i.Message
            };
        });

        // build the dialog
        var dialog = new Dialog({ 
            name: "failedItemList", 
            title: "[resource_displayname[failures]]", 
            width: "1000px", 
            height: "600px", 
            template: "<div name='grid' style='height: 600px;'></div>" 
        });

        dialog.init(function() {
            // build the grid
            var grid = new GridWidget($("[name=grid]", dialog.element), itemData);
            grid.editable = false;
            grid.groupable = false;
            grid.columns = [
                { field: "clientRef", type: "string", title:"[resource_displayname[clientreference]]", width: 120 },
                { field: "transactions", type: "string", title: "[resource_displayname[transactions]]"},
                { field: "message", type: "string", title: "[resource_displayname[problem]]" }
            ];
            grid.init();
        });
    },

    getClientRef: function(item) {
        if(item && item.References) {
           return item.References[0].split("|")[1];
        } else {
            return "";
        }
    }
}
